<template><AppPage :title="item?.resource.provenance.name || 'Volume'" subtitle="VolumePool placement and zone evidence"><v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert><v-alert v-for="observation in relevant" :key="observation.key" type="warning" variant="tonal" class="mb-4">{{ observation.message }}</v-alert><v-skeleton-loader v-if="loading" type="heading,card"/><EvidenceGraph v-else-if="item&&graph" :graph="graph" :root-key="item.resource.key"/></AppPage></template>
<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{sreApi,type SreGraph,type SreResourceDTO,type SreObservation}from'@/api/sre';import AppPage from'@/components/app/AppPage.vue';import EvidenceGraph from'@/components/sre/EvidenceGraph.vue'
const route=useRoute(),item=ref<SreResourceDTO|null>(null),graph=ref<SreGraph|null>(null),observations=ref<SreObservation[]>([]),loading=ref(true),error=ref<string|null>(null),relevant=computed(()=>observations.value.filter(entry=>entry.related?.includes(item.value?.resource.key||'')))
onMounted(async()=>{try{const id=String(route.params.id),[detail,topology,signals]=await Promise.all([sreApi.volume(id),sreApi.graph(id),sreApi.observations()]);item.value=detail.data;graph.value=topology.data;observations.value=signals.data}catch(cause){error.value=cause instanceof Error?cause.message:'Volume unavailable'}finally{loading.value=false}})
</script>
